EX = dict(id="nism-xb", series="X-B", code="NISM Series X-B", short="Investment Adviser Level 2", title="Investment Adviser (Level 2)",
 track="nism-adv", tag="X-B", level="advanced",
 blurb="Advanced planning for SEBI-registered investment advisers: insurance, retirement, tax, estate, behaviour and full financial plans.",
 intro="NISM Series X-B is the advanced module for people who advise clients on complete financial plans. It builds on Level 1 and tests judgement: choosing insurance cover, sizing a retirement corpus, tax-efficient structuring, estate planning, handling client behaviour and putting everything into a coherent plan.",
 who="Registered investment advisers and their principal officers, wealth managers, relationship managers and financial planners who give holistic advice for a fee.",
 qs=120, mins=180, **{"pass": 60}, pass_=60, neg="25% of marks", marks=150, m2=30, days=45,
 glance=[["Format", "Computer-based; 90 one-mark questions and 6 case studies of 5 two-mark questions each"], ["Questions and marks", "120 questions, 150 marks (30 questions carry 2 marks)"], ["Duration", "3 hours"], ["Passing score", "90 marks (60%)"], ["Negative marking", "25% of a question's marks"], ["Prerequisite", "Level 1 (Series X-A) is a usual first step"], ["Where it leads", "Registration and practice as a SEBI investment adviser"]],
 checklist=["Practise retirement corpus and goal-funding sums until they are quick.", "Learn the insurance principles and product differences.", "Revise current tax rates, holding periods and key deductions, and check them against the latest law.", "Learn the six-step planning process and the adviser regulations.", "Take Mock 5 in one 3-hour sitting."],
 tips=["Two-mark case questions need the numbers: build a quick table from the case first.", "Always match the product to the client's need before the return.", "Read assumptions in case questions: inflation, return, tenure.", "Tax questions: check the date and the regime stated in the question.", "In behaviour questions, name the bias by the symptom."],
 sheet=[("Planning process", [["Step", "What happens"], ["1", "Establish the relationship and scope"], ["2", "Gather data and goals"], ["3", "Analyse the position"], ["4", "Recommend a plan"], ["5", "Implement"], ["6", "Monitor and review"]]),
        ("Module marks", [["Module", "Marks"], ["Risk management and insurance", "25"], ["Retirement planning", "30"], ["Taxation", "20"], ["Estate planning", "20"], ["Behavioural finance", "10"], ["Comprehensive advice", "45"]])],
 units=[
 dict(n=1, title="Risk management and insurance planning", w=17,
  overview="25 marks. Identifying risks and choosing insurance to cover them.",
  focus=["Principles of insurance.", "Life, health and general cover.", "Needs analysis.", "Product choice."],
  visuals=[("table", "Insurance products", [["Product", "Core idea"], ["Term plan", "Pure protection, no maturity value"], ["Endowment", "Protection plus savings"], ["ULIP", "Insurance with market-linked investment"], ["Health indemnity", "Pays actual hospital costs"], ["Annuity", "Converts a corpus into income"]], [150, 320])],
  facts=[("Risk management process","The process is to identify risks, measure them, choose a treatment and monitor.","An adviser lists a client's risks and assigns cover.","The process starts with buying a policy."),
   ("Risk treatment options","Risks can be avoided, reduced, retained or transferred; insurance is a way of transferring risk.","A client keeps small risks and insures large ones.","Insurance eliminates all risk."),
   ("Insurable interest","The policyholder must stand to suffer a financial loss if the insured event occurs.","A person can insure a spouse but not an unrelated stranger.","Anyone may insure anyone."),
   ("Utmost good faith","Both parties must disclose all material facts honestly, and non-disclosure can void the claim.","A client who hides a heart condition risks rejection.","Disclosure is needed only at claim time."),
   ("Indemnity","General and health insurance restore the insured to the position before the loss without allowing profit.","A fire policy pays the actual loss up to the sum insured.","Indemnity allows a claim larger than the loss."),
   ("Proximate cause","The claim is payable only if the loss arises from the insured peril as the nearest effective cause.","A loss from an excluded cause is declined.","Any loss is paid if a policy exists."),
   ("Term insurance","Term insurance pays the sum assured on death during the term and nothing on survival, so premiums are low.","A young earner buys a large term cover cheaply.","A term plan returns premiums by default."),
   ("Whole life and endowment","These combine cover with savings and are costlier per rupee of cover than term plans.","An endowment pays on maturity or death.","Endowment plans give the highest cover per premium."),
   ("ULIP","A unit linked plan invests premiums in market funds after charges, with a life cover; it has a five-year lock-in.","A policyholder switches between equity and debt funds.","ULIP returns are guaranteed."),
   ("Human life value","The human life value approach sets cover as the present value of the future earnings that the family would lose.","Cover is based on expected income over working years.","Cover equals current annual expenses only."),
   ("Needs-based approach","The needs approach adds the family's future needs and liabilities and subtracts existing assets to find the cover.","Cover covers loans, goals and living costs net of savings.","Cover is a fixed multiple for everyone."),
   ("Income multiple rule","A rough rule suggests cover of ten to fifteen times annual income, to be refined by a needs analysis.","A first estimate for a young earner.","The multiple is set by law."),
   ("Health insurance","Health policies are indemnity contracts that cover hospital costs up to the sum insured, with waiting periods for pre-existing conditions.","A person buys cover before illness arises.","Health cover applies from the first day for every condition."),
   ("Family floater and individual","A floater shares one sum insured among members, while individual policies give each person a separate sum.","A floater is cheaper but the cover can be exhausted by one member.","A floater gives each member the full sum."),
   ("Deductible and co-payment","In co-payment the insured bears a fixed share of each claim; a deductible is an amount borne before the insurer pays.","A policy requires the insured to pay 20% of each claim.","Co-payment reduces the premium to zero."),
   ("Critical illness cover","A critical illness plan pays a lump sum on diagnosis of a listed illness, regardless of the actual bills.","A benefit policy pays on diagnosis.","It reimburses only actual expenses."),
   ("Personal accident cover","Personal accident cover pays for death or disability caused by accident.","A policy pays for loss of limb in an accident.","It covers illness-related death."),
   ("Disability cover","Income protection or disability cover replaces part of earnings if the person cannot work.","A rider pays a monthly benefit on disability.","Term plans always include disability benefit."),
   ("Motor and home insurance","Third-party motor cover is mandatory; home policies cover structure and contents against listed perils.","A car owner must hold at least the liability cover.","Own-damage motor cover is compulsory."),
   ("Claim settlement ratio","The ratio of claims settled to claims received indicates an insurer's claims record, among other factors for choosing an insurer.","An adviser checks the insurer's record.","The ratio guarantees that every claim will be paid."),
   ("Nomination and assignment","A nominee receives the proceeds as a trustee in many cases, while assignment transfers rights in the policy.","A policyholder updates the nominee after marriage.","A nominee always becomes the legal owner."),
   ("Beneficiary nominee under MWP Act","A policy under the Married Women's Property Act creates a trust for the spouse and children, protecting proceeds from creditors.","A policy is protected from the policyholder's creditors.","MWP policies can be claimed by creditors."),
   ("Free-look period","A new life policy can be returned within the free-look period for a refund subject to deductions.","A buyer cancels the policy within the window.","There is no right to return a policy."),
   ("Riders","Riders add benefits such as accidental death or waiver of premium for an extra cost.","A buyer adds an accident rider.","Riders are always free."),
   ("Insurance as part of the plan","Insurance is for protection; mixing it with investment often leads to poor outcomes in both, so advisers usually separate them.","An adviser recommends term plus mutual funds.","Combination products always beat the two separately."),
   ("Emergency fund and risk","An emergency fund of three to six months of expenses is the first line of defence before insurance.","A client keeps liquid money for shocks.","An emergency fund is not needed with insurance.")]),
 dict(n=2, title="Retirement planning", w=20,
  overview="30 marks. Sizing the corpus, choosing instruments, and planning the payout.",
  focus=["Retirement needs and corpus.", "EPF, PPF, NPS and annuities.", "Withdrawal strategies.", "Longevity and inflation."],
  visuals=[("flow", "Retirement planning steps", ["Estimate expenses", "Inflate to retirement", "Find the corpus", "Compute monthly saving", "Review yearly"]), ("formula", "Corpus idea", "Corpus = Annual expense at retirement / (withdrawal rate)")],
  facts=[("Retirement planning","It estimates the corpus needed to sustain the client's lifestyle after income stops, and the saving needed to reach it.","A 35-year-old plans for retirement at 60.","It focuses only on the date of retirement."),
   ("Inflation impact","Inflation raises future expenses, so the corpus must be based on inflated expenses, not today's.","Expenses of ₹5 lakh today are higher at retirement.","Expenses stay constant during retirement."),
   ("Real rate of return","The real return is the return after adjusting for inflation, roughly nominal less inflation.","A return of 9% with 6% inflation is about 3% real.","The real return equals the nominal return."),
   ("Retirement corpus","The corpus is the amount that, invested at an assumed return, can fund inflation-adjusted expenses for the expected life.","The corpus covers withdrawals up to age 85 or 90.","The corpus only needs to cover five years."),
   ("Safe withdrawal rate","A safe rate such as around 4% of the initial corpus, adjusted for inflation, is used as a rule to avoid depletion.","A corpus of ₹2.5 crore supports ₹10 lakh a year.","Withdrawing 20% a year is safe."),
   ("Longevity risk","Longevity risk is the risk of outliving one's savings, addressed by planning for a long life and using annuities.","A client plans to age 90.","Longevity risk is the risk of dying early."),
   ("Sequence of returns risk","Poor returns in the early years of retirement hurt more because withdrawals deplete the corpus.","A market fall in year one damages the plan.","The order of returns does not matter."),
   ("Bucket strategy","The bucket approach holds near-term needs in safe assets and long-term money in growth assets.","Three years of expenses sit in debt funds.","All money sits in equity."),
   ("Employees' Provident Fund","The EPF is a mandatory retirement scheme where employee and employer both contribute 12% of basic pay, with a rate declared annually.","A salaried person's retirement base.","EPF offers a fixed guaranteed rate for life."),
   ("Public Provident Fund","The PPF has a 15-year tenure, an annual limit of ₹1.5 lakh and a government-set rate, with tax-free interest and maturity under current rules.","An investor opens a PPF for long-term saving.","PPF has a 5-year tenure."),
   ("National Pension System","The NPS is a market-linked pension scheme; the Tier I account has restricted withdrawals, and at 60 up to 60% may be taken as a lump sum with the rest used to buy an annuity.","A subscriber buys an annuity with part of her corpus.","NPS allows full free withdrawal at any time."),
   ("NPS asset choices","NPS subscribers choose between active choice and auto choice, with different limits for equity exposure.","An investor selects the lifecycle option.","NPS offers only government securities."),
   ("Annuity","An annuity converts a corpus into a regular income, for life or a fixed period, in exchange for a lump sum.","A retiree buys an annuity for steady income.","An annuity is a growth investment."),
   ("Immediate versus deferred annuity","An immediate annuity starts paying soon after purchase, while a deferred annuity starts after an accumulation phase.","A retiree needing income buys an immediate annuity.","A deferred annuity pays at once."),
   ("Annuity with return of purchase price","This option pays income for life and returns the purchase price to the nominee on death, with a lower payout.","A retiree wants to leave money to her heirs.","It gives a higher payout than the life-only option."),
   ("Senior Citizens' Savings Scheme","SCSS is a government scheme for those aged 60 and above with a 5-year tenure, a quarterly interest payout and an investment cap.","A retiree seeks safe regular income.","SCSS is open to all ages."),
   ("Atal Pension Yojana","APY gives a guaranteed pension of ₹1,000 to ₹5,000 a month at 60 for contributors in the unorganised sector.","A small earner chooses a fixed pension.","APY pays a market-linked pension."),
   ("Systematic withdrawal plan","An SWP withdraws a fixed amount from a mutual fund regularly, providing income while the balance stays invested.","A retiree draws monthly from a debt fund.","An SWP sells the whole fund at once."),
   ("Retirement income sources","Sources include pension, rental income, interest, dividends and annuities, and the adviser should map them against expenses.","An adviser tabulates income against needs.","Only one source is needed."),
   ("Reverse mortgage","A reverse mortgage lets a senior citizen borrow against the home and receive regular payments with no repayment during life.","A homeowner draws income against the property.","The borrower makes monthly repayments."),
   ("Healthcare in retirement","Medical costs rise faster than general inflation, so health cover and a medical reserve are part of the plan.","A plan sets aside a health fund.","Healthcare costs fall after retirement."),
   ("Savings needed per month","The monthly saving is found by working out the future value of a series of investments needed to reach the corpus.","A planner solves for the SIP to reach ₹3 crore.","Savings are computed without any return assumption."),
   ("Replacement ratio","The replacement ratio is post-retirement income as a share of pre-retirement income, often taken at 60 to 80%.","A client plans for 70% of the last salary.","Replacement ratio is always 100%."),
   ("Glide path","As retirement nears, the equity share is reduced gradually to protect the corpus.","A lifecycle fund shifts to debt with age.","Equity is raised as retirement nears."),
   ("Early retirement","Retiring earlier increases the corpus needed because there are fewer saving years and more years to fund.","A client wants to retire at 45.","Early retirement lowers the required corpus."),
   ("Retirement and tax","Pension and annuity income are taxed as income, and tax on withdrawals depends on the product and the rules in force.","An annuity payout is added to taxable income.","Annuities are always tax-free."),
   ("Review and rebalancing","A retirement plan is reviewed every year for changes in expenses, returns, health and goals.","The adviser reviews assumptions annually.","A plan is set once and never reviewed.")]),
 dict(n=3, title="Taxation", w=13,
  overview="20 marks. Tax treatment of income and investments, and tax-efficient planning. Rates change; check the latest law.",
  focus=["Heads of income.", "Capital gains.", "Deductions and regimes.", "Tax-efficient investing."],
  visuals=[("note", "Check the date", "Tax rates, slabs and limits change in each Budget. The facts here follow the law at the time of writing; always verify current figures before advising a client or answering a question that names a financial year.", "gold"), ("table", "Capital gains (listed equity)", [["Holding", "Type", "Rate"], ["Up to 12 months", "Short term", "20%"], ["More than 12 months", "Long term", "12.5% above ₹1.25 lakh a year"]], [180, 140, 150])],
  facts=[("Heads of income","Income is classified as salary, house property, business or profession, capital gains and other sources.","Rent is taxed under house property.","All income is taxed under one head."),
   ("Residential status","Tax liability depends on residential status; residents are taxed on global income and non-residents on India-sourced income.","An NRI is taxed on income earned in India.","Residents are taxed only on Indian income."),
   ("Old and new regime","Individuals can choose between the old regime with deductions and the new regime with lower slab rates and few deductions.","A client with large deductions compares both.","Deductions like 80C apply under the new regime."),
   ("Section 80C","Section 80C allows a deduction up to ₹1.5 lakh for items such as PPF, ELSS, life insurance premiums and EPF in the old regime.","A client invests in ELSS for deduction.","80C allows unlimited deduction."),
   ("ELSS","Equity Linked Savings Schemes are tax-saving mutual funds with a three-year lock-in.","A client chooses ELSS under 80C.","ELSS has a 15-year lock-in."),
   ("Section 80D","Section 80D allows a deduction for health insurance premiums, with higher limits for senior citizens, in the old regime.","A client claims the premium paid for her parents.","80D covers life insurance premiums."),
   ("Section 80CCD(1B)","An additional deduction of up to ₹50,000 is available for NPS contributions, over and above 80C, in the old regime.","A client adds to NPS for extra deduction.","The extra deduction is ₹5 lakh."),
   ("Standard deduction","Salaried individuals get a flat standard deduction from salary income, and the amount differs by regime.","A salaried person gets it without any proof.","The standard deduction needs bills."),
   ("Short-term capital gains on equity","Gains on listed equity shares and equity funds held up to 12 months are short term and taxed at a flat rate, currently 20%.","A fund sold after 8 months.","Short-term gains on equity are taxed at 15% always."),
   ("Long-term capital gains on equity","Gains on listed equity held for more than 12 months are taxed at 12.5% on the amount above the annual exemption of ₹1.25 lakh.","A holder sells after two years.","LTCG on equity is fully exempt."),
   ("Debt mutual funds","Debt funds bought after April 2023 are taxed on gains at the investor's slab rate, whatever the holding period.","A debt fund gain is added to income.","Debt funds get indexation benefit."),
   ("Holding period for other assets","Unlisted shares and immovable property need two years to be long term, and long-term gains are taxed at 12.5% without indexation under current rules.","A flat sold after 3 years.","Property is long term after one year."),
   ("Gold","Gold is long term after 24 months, with gains taxed at 12.5% under current rules, while gold funds follow their own rules.","Physical gold sold after 3 years.","Gold is long term after one year."),
   ("Set-off and carry forward","Capital losses can be set off against capital gains and carried forward for eight years, but long-term losses only against long-term gains.","A short-term loss reduces long-term gain.","Long-term loss offsets any income."),
   ("Dividend taxation","Dividends are taxed in the hands of the recipient at the slab rate.","Dividend income is added to total income.","Dividends are tax-free for all investors."),
   ("Interest income","Interest from bank deposits is taxable at slab rates, with TDS above specified limits.","FD interest is added to income.","FD interest is tax-free."),
   ("TDS","Tax deducted at source is a prepayment of tax by the payer and can be adjusted in the return.","A bank deducts tax on interest.","TDS is a separate additional tax."),
   ("Advance tax","Taxpayers expecting liability above a threshold pay advance tax in instalments through the year.","A business pays four times a year.","Advance tax is paid after the year ends."),
   ("Rental income","Rent is taxed under house property after a standard deduction of 30% of net annual value, plus home loan interest deduction subject to limits.","A landlord claims a 30% deduction.","Rent is exempt from tax."),
   ("Home loan benefits","Interest on a home loan is deductible within limits for a self-occupied house, with principal repayment qualifying under 80C in the old regime.","A borrower claims interest up to the limit.","There is no tax benefit from a home loan."),
   ("HUF","A Hindu Undivided Family is taxed as a separate entity, which allows another set of exemptions and slabs.","A family splits income between itself and an HUF.","HUF is not a separate taxpayer."),
   ("Clubbing of income","Income from assets transferred to a spouse or minor child without adequate consideration is clubbed with the transferor's income.","A gift to a spouse that earns interest is taxed in the giver's hands.","Gifts to a spouse always shift the tax."),
   ("Gifts","Gifts from specified relatives are exempt, while gifts from others above a threshold are taxed as income of the recipient.","A gift from a parent is exempt.","All gifts are taxed."),
   ("Tax harvesting","Booking long-term gains up to the exemption limit each year and re-investing can reduce future tax.","An investor sells units to use the annual exemption.","Tax harvesting avoids all tax."),
   ("Tax planning versus evasion","Planning uses legal provisions to reduce tax, while evasion hides income or misreports and is illegal.","A client uses deductions properly.","Hiding income is tax planning.")]),
 dict(n=4, title="Estate planning", w=13,
  overview="20 marks. Passing wealth smoothly through wills, nominations, trusts and succession law.",
  focus=["Wills and probate.", "Succession laws.", "Trusts.", "Nomination versus legal heirs."],
  visuals=[("table", "Nominee vs legal heir", [["Point", "Nominee", "Legal heir"], ["Role", "Receives, often as trustee", "Entitled by law or will"], ["Ownership", "Not automatic owner", "Owns the share"], ["Basis", "Nomination form", "Succession law / will"]], [110, 180, 180])],
  facts=[("Estate planning","Estate planning arranges how assets will pass to the next generation, minimising disputes, delay and cost.","A client documents her wishes while alive.","It begins only after death."),
   ("Will","A will is a legal declaration of how a person wants her property distributed after death, and it takes effect only on death.","A testator names her heirs in a signed will.","A will operates from the date of signing."),
   ("Testator and executor","The testator makes the will and the executor is the person appointed to carry it out.","A friend named to execute the will.","The executor makes the will."),
   ("Valid will","A will must be in writing, signed by the testator and attested by two witnesses, and registration is optional.","A will signed before two witnesses.","Registration is compulsory."),
   ("Revoking a will","A will can be changed or revoked any time before death, and a later will overrides the earlier one.","A client writes a new will after marriage.","A will cannot be changed after signing."),
   ("Intestate succession","If a person dies without a will, the property passes according to personal succession laws.","A man dies without a will and the law decides.","The state takes the property."),
   ("Hindu Succession Act","This Act governs intestate succession among Hindus, with equal rights for sons and daughters in coparcenary property.","A daughter inherits equally.","Daughters have no rights under the Act."),
   ("Indian Succession Act","This Act governs wills and succession for Christians and others, and the rules for probate of wills.","A will's probate rules.","It applies only to Hindus."),
   ("Muslim personal law","Muslims follow personal law for succession, with defined shares, and a will is limited to a share of the estate.","A Muslim testator is limited in the portion she can will away.","A Muslim may will away the whole estate freely."),
   ("Probate","Probate is the court's certification that a will is genuine and gives the executor authority to act.","An executor obtains it to transfer assets.","Probate is a tax on the estate."),
   ("Nomination","A nominee receives assets on the holder's death but may hold them for the legal heirs, depending on the law that applies.","A bank pays a nominee and the nominee holds it for heirs.","A nominee overrides the will in all cases."),
   ("Legal heirs","Legal heirs are the persons entitled under succession law or a will, and they can claim assets irrespective of nomination in many cases.","Heirs may claim the share from the nominee.","Legal heirs have no claim if a nominee exists."),
   ("Succession certificate","A succession certificate lets the heirs of a person who died without a will collect debts and securities.","Heirs obtain it to claim bank dues.","It is required for all wills."),
   ("Trust","A trust holds property for the benefit of others under a trustee, allowing control, privacy and protection.","A settlor creates a trust for her children.","A trust is a type of will."),
   ("Settlor, trustee, beneficiary","The settlor creates the trust, the trustee manages it and the beneficiary gets the benefits.","The trustee manages assets for the beneficiary.","The beneficiary manages the trust."),
   ("Revocable and irrevocable trust","A revocable trust can be changed or ended by the settlor, while an irrevocable trust cannot, giving stronger separation of assets.","A settlor retains the power to cancel the trust.","An irrevocable trust can be withdrawn easily."),
   ("Private trust","A private trust may be set up for the family to hold assets, manage inheritance and protect minors or dependants.","A family trust holds a business stake.","A private trust must be registered as a charity."),
   ("Power of attorney","A power of attorney authorises another person to act for the principal during life and ends on the principal's death.","An agent signs documents when the owner is abroad.","A power of attorney continues after death."),
   ("Gifting","Gifting during life transfers ownership immediately via a gift deed, and property gifts require registration.","A parent gifts a flat to a child by registered deed.","An oral gift of property is valid."),
   ("Inheritance tax","India has no inheritance or estate tax at present, but income from inherited assets is taxable to the heir.","An heir pays tax on rent from an inherited flat.","India taxes the transfer on inheritance."),
   ("Cost of inherited assets","For capital gains, the cost of an inherited asset is the cost to the previous owner and the holding period includes the previous holder's period.","An heir sells an inherited house.","The cost is the value on the date of death only."),
   ("Joint holding","In a joint account with 'either or survivor', the surviving holder operates the account on the death of the other.","A spouse continues to access the account.","Joint accounts are frozen on any death."),
   ("Guardian for minors","A will can name a guardian for minor children, and a trust can manage their assets until adulthood.","A parent appoints a guardian in the will.","Minors can hold and sell property directly."),
   ("Family settlement","A family settlement is an arrangement among family members to divide property and avoid disputes.","Siblings agree on the division of assets in writing.","A family settlement needs no document."),
   ("Review of estate plan","The plan should be updated after marriage, birth, divorce, death or major changes in assets.","A client updates the will after a new child.","An estate plan never needs revision.")]),
 dict(n=5, title="Behavioural finance", w=7,
  overview="10 marks. Recognising biases in clients and in oneself.",
  focus=["Cognitive and emotional biases.", "Prospect theory.", "Managing client behaviour."],
  visuals=[("table", "Biases by symptom", [["Symptom", "Bias"], ["Holds losers, sells winners", "Disposition effect"], ["Fixates on purchase price", "Anchoring"], ["Follows the crowd", "Herding"], ["Pain of loss > joy of gain", "Loss aversion"], ["Separates money into pots", "Mental accounting"]], [260, 210])],
  facts=[("Behavioural finance","It studies how psychology influences financial decisions and markets, in contrast to the view that investors are always rational.","A client panics and sells in a fall.","It assumes investors always act rationally."),
   ("Prospect theory","Prospect theory says people value gains and losses relative to a reference point and feel losses more strongly than equal gains.","A client dislikes a loss more than she likes the same gain.","It says people weigh gains and losses equally."),
   ("Loss aversion","Loss aversion is the tendency to feel the pain of a loss more than the pleasure of an equal gain.","A client refuses to sell a stock at a loss.","Loss aversion makes clients take more risk."),
   ("Disposition effect","Investors tend to sell winners too early and hold losers too long.","A client books a small profit but keeps a falling stock.","Investors sell losers quickly."),
   ("Anchoring","Anchoring is relying heavily on an initial number, like the purchase price, when making decisions.","A client waits for a price to return to her buying level.","Anchoring is making decisions using fresh information."),
   ("Overconfidence","Overconfident investors overestimate their knowledge and ability, trade too often and under-diversify.","A client believes she can time the market.","Overconfidence reduces trading."),
   ("Herding","Herding is following the actions of the crowd rather than one's own analysis.","Clients rush into a rising stock because others do.","Herding means making independent decisions."),
   ("Confirmation bias","Confirmation bias is seeking information that supports existing beliefs and ignoring contrary evidence.","A client reads only positive news on her holding.","It means testing views against evidence."),
   ("Recency bias","Recency bias gives too much weight to recent events and extrapolates them into the future.","A client assumes last year's rally will continue.","Recency bias values long-term history."),
   ("Availability bias","Judging the likelihood of an event by how easily examples come to mind.","A client avoids equity after hearing of a crash.","It means using full statistics."),
   ("Mental accounting","People treat money differently depending on its source or purpose, such as treating a bonus as free money.","A client spends a windfall recklessly.","It treats all money as the same."),
   ("Endowment effect","People value what they own more than identical things they do not own.","A client refuses to sell an inherited stock.","It means pricing assets at market value."),
   ("Status quo bias","A preference to keep things as they are and avoid change.","A client leaves money idle in a savings account.","It drives clients to rebalance often."),
   ("Regret aversion","Avoiding decisions that may cause regret, leading to inaction or following the crowd.","A client delays investing for fear of a fall.","It makes clients eager to take bold bets."),
   ("Framing","The way information is presented influences the decision, even when facts are the same.","A fund described as 90% success is liked more than one with 10% failure.","Framing has no effect on choices."),
   ("Cognitive and emotional biases","Cognitive biases arise from faulty reasoning and can be reduced with information, while emotional biases arise from feelings and are harder to correct, so the adviser adapts to them.","An adviser accepts an emotional bias and designs around it.","Emotional biases are easy to remove with data."),
   ("Managing client behaviour","Advisers help by setting a written policy, pre-agreeing rebalancing rules and using goal-based buckets to reduce emotional decisions.","A written plan guides a client during a fall.","Advisers should follow every client impulse."),
   ("Self-attribution","Crediting success to skill and failure to bad luck.","An investor claims her gains came from her analysis only.","Self-attribution leads to learning from errors.")]),
 dict(n=6, title="Comprehensive financial advice", w=30,
  overview="45 marks, the largest module. Putting everything together: process, regulation, risk profile, allocation, plan and review. Most case studies sit here.",
  focus=["Planning process.", "SEBI IA regulations.", "Risk profile and asset allocation.", "Goals, cash flow and net worth.", "Case-style problems."],
  visuals=[("flow", "Planning process", ["Engage and set scope", "Gather data", "Analyse", "Recommend", "Implement", "Monitor"]), ("keynums", [("₹1.51 lakh", "Fee cap per family per year"), ("40%", "EMI to income guide"), ("3 to 6", "Months of emergency fund")])],
  facts=[("Financial planning","Financial planning is a process of meeting life goals through the proper management of finances.","A plan links goals, cash flow, risk and investments.","It is the same as selling products."),
   ("Six-step process","The steps are establishing the relationship, gathering data, analysing, recommending, implementing and monitoring.","The adviser reviews the plan after it is implemented.","Monitoring is optional once the plan starts."),
   ("SEBI Investment Advisers Regulations","Anyone giving investment advice for a fee must be registered with SEBI under the 2013 regulations.","A fee-charging adviser needs registration.","Anyone may give paid advice without registration."),
   ("Qualification and certification","Individual advisers need prescribed qualification and a NISM certification such as Series X-A and X-B, as the rules specify.","An adviser passes the NISM certification.","No certification is required."),
   ("Fee structure","Advisers may charge a fixed fee or a fee linked to assets under advice, within a cap on fees from an individual or family per year, currently ₹1.51 lakh.","A client pays a fixed annual fee.","Advisers may take commission from products they recommend."),
   ("Segregation","Advisory and distribution activities must be separated, and advisers cannot receive distribution commission from clients they advise.","An adviser recommends direct plans.","An adviser may earn commissions from the same client."),
   ("Risk profiling","Risk profiling assesses a client's willingness, ability and need to take risk before recommending investments.","A questionnaire and cash-flow review feed the profile.","Risk profiling is based on age alone."),
   ("Risk tolerance and risk capacity","Tolerance is the willingness to bear risk, and capacity is the financial ability to bear it; the lower one governs.","A willing client with little savings gets a cautious plan.","Tolerance always determines the plan."),
   ("Suitability","Advice must be suitable to the client's profile, and the adviser must document the basis for recommendations.","A written rationale accompanies each recommendation.","Suitability is checked once a decade."),
   ("Conflict of interest","Advisers must disclose conflicts of interest and manage them in the client's favour.","An adviser discloses a relationship with a provider.","Conflicts need not be disclosed."),
   ("Risk profile report and agreement","Advisers must keep the signed agreement, risk profile and advice records for the prescribed period.","The adviser retains records for the period required.","Records are optional."),
   ("Goal-based planning","Goals are listed with amount, time horizon and priority, inflation-adjusted and matched with suitable investments.","A child's education in 12 years is funded by equity-oriented funds.","All goals are funded with the same asset."),
   ("Asset allocation","Asset allocation divides a portfolio among asset classes according to goals, horizon and risk, and drives most of the variation in returns.","A balanced client holds equity and debt.","Asset allocation is about picking one winning stock."),
   ("Strategic and tactical allocation","Strategic allocation sets long-term target weights while tactical allocation makes short-term deviations to exploit views.","A client's long-run mix is 60:40.","Tactical allocation is a fixed rule."),
   ("Rebalancing","Rebalancing returns the portfolio to target weights after market moves, by calendar or by threshold.","A portfolio is reset when equity drifts above its band.","Rebalancing means adding only to winners."),
   ("Emergency fund","The emergency fund of three to six months of expenses is kept in liquid, safe instruments.","Funds are kept in a liquid fund.","The emergency fund should be in small-cap equity."),
   ("Cash flow statement","A cash flow statement lists inflows and outflows in a period to find the surplus available for goals.","A planner finds a monthly surplus.","It shows the client's net worth."),
   ("Net worth statement","Net worth is the difference between assets and liabilities at a date.","Assets of ₹1 crore less loans of ₹30 lakh give ₹70 lakh.","Net worth is annual income minus expenses."),
   ("Debt ratios","A common guide is that EMIs should not exceed about 40% of income and total debt service should be sustainable.","A client with EMIs of 55% of income is over-leveraged.","There is no useful guide on borrowing."),
   ("Savings ratio","The savings ratio is savings as a share of income and shows the client's capacity to fund goals.","A saver putting away 25% of income.","Savings ratio is expenses divided by income."),
   ("Liquidity ratio","The liquidity ratio is liquid assets divided by monthly expenses and shows how many months the client can cope without income.","Liquid assets of ₹3 lakh with expenses of ₹50,000 give 6 months.","It measures the share of equity in the portfolio."),
   ("Time value of money","A rupee today is worth more than a rupee in the future because it can earn a return.","Planning uses present and future values.","Money has the same value at all times."),
   ("Future value","Future value is the amount an investment grows to at a given rate over a period.","₹1 lakh at 10% for 2 years becomes ₹1.21 lakh.","Future value is calculated by dividing by growth."),
   ("Present value","Present value discounts a future amount to today's equivalent at a given rate.","₹1.21 lakh in 2 years at 10% is worth ₹1 lakh today.","Present value is greater than future value for positive rates."),
   ("SIP for a goal","The monthly investment required for a goal is found from the future value of an annuity, given the expected return and time.","A planner sets the SIP for a target corpus.","A SIP amount does not depend on time horizon."),
   ("CAGR","The compound annual growth rate expresses the annualised growth between two values over a period.","₹100 growing to ₹200 in 5 years is about 14.9% a year.","CAGR is the simple average of yearly returns."),
   ("Time-weighted return","Time-weighted return removes the effect of cash flows to measure the manager's performance.","A fund's return is compared over a period fairly.","It depends on the timing of the client's deposits."),
   ("Sharpe ratio","The Sharpe ratio is excess return over the risk-free rate divided by standard deviation and measures return per unit of total risk.","A higher Sharpe ratio is better for equal risk.","The Sharpe ratio uses beta as the risk measure."),
   ("CAPM","CAPM gives the required return as the risk-free rate plus beta times the market risk premium.","Risk-free 7%, market premium 6%, beta 1.2 gives 14.2%.","CAPM uses standard deviation as the risk."),
   ("Diversification","Spreading investments across assets with low correlation reduces risk without proportionally lowering return.","A portfolio holds equity, debt and gold.","Diversification removes market risk entirely."),
   ("Mutual fund selection","Selection looks at risk-adjusted returns, consistency, cost, portfolio quality and the manager, and prefers direct plans for advisers.","An adviser compares expense ratios and Sharpe ratios.","Last year's top return is the only criterion."),
   ("Direct versus regular plans","Direct plans have lower expense ratios because no distributor commission is paid, which matters for fee-only advisers.","A client's returns improve by choosing direct plans.","Direct plans carry higher costs."),
   ("Client communication","Communication should be clear, in the client's language, honest about risks and avoiding jargon and promises.","An adviser explains the plan's assumptions.","Guaranteeing returns builds trust."),
   ("Plan monitoring","The plan is reviewed at least annually and when life events, markets or goals change.","A marriage triggers a review.","Reviews are only needed on request."),
   ("Insurance and debt in the plan","A good plan first secures protection and removes costly debt before building long-term wealth.","A client repays a high-interest loan before investing more.","Costly debt should be kept while investing."),
   ("Special situations","Advisers adapt plans for business owners, senior citizens, NRIs and clients with irregular income.","A seasonal earner holds a larger buffer.","One standard plan fits every client."),
   ("Ethics and fiduciary duty","The adviser acts in the client's best interest, with integrity, confidentiality and care.","An adviser puts the client's interest above her own.","The adviser's duty is to maximise her fee."),
   ("Grievance redressal","Clients can complain to the adviser, then SEBI through its portal, and the adviser must act on complaints promptly.","A client files on SCORES.","Advisers are not subject to complaints."),
   ("Cases: reading the facts","In case questions, extract the client's goals, income, assets, liabilities, risk profile and assumptions into a table before answering.","A candidate tabulates the case before solving.","Case answers can be guessed without the data.")]),
])
